# The Round Table Convenes for Testing

*draws Excalibur, its light illuminating the testing scrolls*

We are all equals at the Round Table. Let us coordinate our test strategy as such.

```typescript
import { render, screen, waitFor } from '@testing-library/react';
import userEvent from '@testing-library/user-event';
import { describe, it, expect, vi, beforeEach } from 'vitest';
import { Checkout } from './Checkout';
import { CartProvider } from './CartContext';
import { PaymentProvider } from './PaymentContext';

const mockItems = [
  { id: '1', name: 'Excalibur Replica', price: 299.99 },
  { id: '2', name: 'Round Table Coaster', price: 19.99 }
];

const mockProcessPayment = vi.fn();

const renderCheckout = (cartItems = mockItems) => {
  return render(
    <CartProvider initialItems={cartItems}>
      <PaymentProvider processPayment={mockProcessPayment}>
        <Checkout onComplete={vi.fn()} onCancel={vi.fn()} />
      </PaymentProvider>
    </CartProvider>
  );
};

describe('Checkout - The Quest Proceeds', () => {
  beforeEach(() => {
    vi.clearAllMocks();
  });

  describe('Happy Path - Complete Victory', () => {
    it('completes full checkout flow from shipping to confirmation', async () => {
      const user = userEvent.setup();
      mockProcessPayment.mockResolvedValue({ orderId: 'CAMELOT-123' });
      renderCheckout();

      // Shipping step
      await user.type(screen.getByLabelText(/street address/i), '1 Camelot Way');
      await user.type(screen.getByLabelText(/city/i), 'Camelot');
      await user.selectOptions(screen.getByLabelText(/state/i), 'CA');
      await user.type(screen.getByLabelText(/zip code/i), '90210');
      await user.click(screen.getByRole('button', { name: /continue to payment/i }));

      // Payment step
      await user.type(screen.getByLabelText(/card number/i), '4111111111111111');
      await user.type(screen.getByLabelText(/expiry/i), '12/25');
      await user.type(screen.getByLabelText(/cvv/i), '123');
      await user.type(screen.getByLabelText(/name on card/i), 'King Arthur');
      await user.click(screen.getByRole('button', { name: /review order/i }));

      // Review step
      expect(screen.getByText(/excalibur replica/i)).toBeInTheDocument();
      await user.click(screen.getByRole('button', { name: /place order/i }));

      // Confirmation
      await waitFor(() => {
        expect(screen.getByText(/order confirmed/i)).toBeInTheDocument();
        expect(screen.getByText('CAMELOT-123')).toBeInTheDocument();
      });
    });
  });

  describe('Validation - Guarding the Gates', () => {
    it('displays error for invalid ZIP code', async () => {
      const user = userEvent.setup();
      renderCheckout();

      await user.type(screen.getByLabelText(/zip code/i), 'invalid');
      await user.click(screen.getByRole('button', { name: /continue/i }));

      expect(screen.getByRole('alert')).toHaveTextContent(/valid zip/i);
    });

    it('marks invalid fields with aria-invalid', async () => {
      const user = userEvent.setup();
      renderCheckout();

      await user.click(screen.getByRole('button', { name: /continue/i }));

      expect(screen.getByLabelText(/street/i)).toHaveAttribute('aria-invalid', 'true');
    });
  });

  describe('Error States - Recovering from Defeat', () => {
    it('displays payment error and allows retry', async () => {
      mockProcessPayment.mockRejectedValueOnce(new Error('Card declined'));
      // ...complete flow to review, click place order

      await waitFor(() => {
        expect(screen.getByRole('alert')).toHaveTextContent(/card declined/i);
      });
      expect(screen.getByRole('button', { name: /place order/i })).toBeEnabled();
    });
  });

  describe('Edge Cases - Empty Cart', () => {
    it('shows empty cart message when no items', () => {
      renderCheckout([]);
      expect(screen.getByRole('alert')).toHaveTextContent(/cart is empty/i);
    });
  });

  describe('Loading States', () => {
    it('disables buttons and shows processing during submission', async () => {
      mockProcessPayment.mockImplementation(() => new Promise(() => {}));
      // ...navigate to review step

      await user.click(screen.getByRole('button', { name: /place order/i }));

      expect(screen.getByRole('button', { name: /processing/i })).toBeDisabled();
      expect(screen.getByRole('button', { name: /processing/i })).toHaveAttribute('aria-busy', 'true');
    });
  });
});
```

Excalibur lights the way. These tests guard behavior, not implementation—as true knights defend the realm, not its castle walls.
